package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import dustin.cex.domains.order.service.*;
import dustin.cex.domains.order.repository.*;
import dustin.cex.domains.balance.repository.UserBalanceRepository;
import dustin.cex.domains.ledger.LedgerService;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.support.*;

/** 실제 PG의 취소 원본/필수 감사와 금융 결과 소비 경계를 검증한다. 엔진 통신만 합성이다. */
class OrderCancellationIntegrationTest extends EddTestSupport {
    @Autowired OrderService orders;@Autowired OrderCancellationService cancellation;
    @Autowired OrderRepository orderRows;@Autowired OrderSubmissionRepository submissions;
    @Autowired OrderCancellationRepository cancellations;@Autowired UserBalanceRepository balances;
    @Autowired LedgerService ledger;@Autowired dustin.cex.shared.kafka.KafkaOrderEventConsumer consumer;
    long orderId,ledgerCount;
    @BeforeEach void reserved()throws Exception{
        verify(false);allowed();
        balances.saveAndFlush(dustin.cex.domains.balance.model.entity.UserBalance.builder().userId(customer.getId()).mintAddress("USDT").available(new BigDecimal("1000")).locked(BigDecimal.ZERO).build());ledger.initializeOpening();
        when(fees.getFeeConfig("BTC","USDT")).thenReturn(dustin.cex.domains.fee.model.entity.FeeConfig.builder().feeRate(BigDecimal.ZERO).feeType("both").isActive(true).build());
        when(engine.submitOrder(anyLong(),anyLong(),anyString(),anyString(),anyString(),anyString(),any(),any(),any())).thenReturn(true);
        var command=dustin.cex.domains.order.model.dto.CreateOrderRequest.builder().baseMint("BTC").quoteMint("USDT").orderType("buy").orderSide("limit").price(new BigDecimal("10000")).amount(new BigDecimal("0.001")).build();
        orderId=Long.parseLong(orders.createOrder(customer.getId(),UUID.randomUUID(),command).response().getOrder().getId());ledgerCount=jdbc.queryForObject("SELECT count(*) FROM ledger_entries",Long.class);clearInvocations(engine,producer,client);
        when(engine.cancelOrder(orderId,customer.getId(),"BTC/USDT")).thenReturn(true);
    }
    void request(){orders.cancelOrder(customer.getId(),orderId);}
    long requests(){return jdbc.queryForObject("SELECT count(*) FROM order_cancellations",Long.class);}
    void unchanged(){var b=balances.findByUserIdAndMintAddress(customer.getId(),"USDT").orElseThrow();assertEquals(0,new BigDecimal("990").compareTo(b.getAvailable()));assertEquals(0,new BigDecimal("10").compareTo(b.getLocked()));assertEquals(ledgerCount,jdbc.queryForObject("SELECT count(*) FROM ledger_entries",Long.class));assertEquals("pending",orderRows.findById(orderId).orElseThrow().getStatus());}
    @Test void durableAcknowledgementDoesNotReleaseReservationBeforeKafka(){request();assertNotNull(cancellations.findById(orderId).orElseThrow().getAcknowledgedAt());unchanged();org.mockito.Mockito.verify(engine,times(1)).cancelOrder(orderId,customer.getId(),"BTC/USDT");}
    @Test void theActualFinancialEventReleasesOnceAndStopsFurtherRetry(){
        request();UUID source=UUID.randomUUID();String raw=json.writeValueAsString(Map.of("event_id",source+":1:0","engine_id",source,"event_type","order_cancelled","order_id",Long.toString(orderId),"user_id",customer.getId(),"base_mint","BTC","quote_mint","USDT"));
        consumer.consumeOrderEvent(raw);consumer.consumeOrderEvent(raw);assertFalse(cancellation.retryNext());
        var b=balances.findByUserIdAndMintAddress(customer.getId(),"USDT").orElseThrow();assertEquals(0,new BigDecimal("1000").compareTo(b.getAvailable()));assertEquals(0,BigDecimal.ZERO.compareTo(b.getLocked()));assertEquals("cancelled",orderRows.findById(orderId).orElseThrow().getStatus());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM ledger_transactions WHERE kind='CANCELLED'",Long.class));org.mockito.Mockito.verify(engine,times(1)).cancelOrder(orderId,customer.getId(),"BTC/USDT");
    }
    @Test void aMissingInitialAuditRollsBackTheRequestBeforeEveryExternalCall(){doNothing().when(audit).record(eq(customer.getId()),eq("ORDER_CANCEL_REQUESTED"),anyString(),anyString(),anyString());assertThrows(org.springframework.dao.DataAccessException.class,()->request());assertEquals(0,requests());verifyNoInteractions(engine);unchanged();}
    @Test void aThrowingInitialAuditRollsBackTheRequest(){doThrow(new IllegalStateException("격리 취소 감사 실패")).when(audit).record(eq(customer.getId()),eq("ORDER_CANCEL_REQUESTED"),anyString(),anyString(),anyString());assertThrows(RuntimeException.class,()->request());assertEquals(0,requests());verifyNoInteractions(engine);unchanged();}
    @Test void claimAuditFailureLeavesACommittedIntentWithoutExternalDelivery(){doThrow(new IllegalStateException("격리 청구 감사 실패")).when(audit).record(isNull(),eq("ORDER_CANCEL_ATTEMPT_STARTED"),anyString(),anyString(),anyString());request();assertEquals(1,requests());assertEquals(0,cancellations.findById(orderId).orElseThrow().getAttempts());verifyNoInteractions(engine);unchanged();}
    @Test void responseAuditFailureDoesNotCommitAnAcknowledgement(){doThrow(new IllegalStateException("격리 응답 감사 실패")).when(audit).record(isNull(),eq("ORDER_CANCEL_ATTEMPT_FINISHED"),anyString(),anyString(),anyString());request();var q=cancellations.findById(orderId).orElseThrow();assertEquals(1,q.getAttempts());assertNull(q.getAcknowledgedAt());unchanged();}
    @Test void responseLossKeepsTheIntentAndTheFinancialReservation(){when(engine.cancelOrder(orderId,customer.getId(),"BTC/USDT")).thenThrow(new IllegalStateException("격리 응답 유실"));request();var q=cancellations.findById(orderId).orElseThrow();assertEquals(1,q.getAttempts());assertNull(q.getAcknowledgedAt());unchanged();}
    @Test void currentTradingRestrictionDoesNotPreventRiskReducingOwnCancellation(){var u=users.findById(customer.getId()).orElseThrow();u.setTradingRestricted(true);users.saveAndFlush(u);request();assertEquals(1,requests());unchanged();}
    @Test void theSameRequestDoesNotAppendAnotherIntentOrEngineCommand(){request();request();assertEquals(1,requests());org.mockito.Mockito.verify(engine,times(1)).cancelOrder(orderId,customer.getId(),"BTC/USDT");unchanged();}
    @Test void directSqlCannotCreateARequestForAnotherCustomer(){assertThrows(org.springframework.dao.DataAccessException.class,()->new TransactionTemplate(manager).executeWithoutResult(t->{jdbc.update("INSERT INTO order_cancellations(order_id,user_id,base_mint,quote_mint,requested_at,attempts,next_attempt_at) VALUES(?,?,?, ?,clock_timestamp(),0,clock_timestamp())",orderId,maker.user().getId(),"BTC","USDT");audit.record(maker.user().getId(),"ORDER_CANCEL_REQUESTED","order:"+orderId,"SUCCESS","INTENT_ONLY_ENGINE_RESULT_FOLLOWS");}));assertEquals(0,requests());unchanged();}
    @Test void directSqlCannotReplaceTheOriginalMarket(){assertThrows(org.springframework.dao.DataAccessException.class,()->new TransactionTemplate(manager).executeWithoutResult(t->{jdbc.update("INSERT INTO order_cancellations(order_id,user_id,base_mint,quote_mint,requested_at,attempts,next_attempt_at) VALUES(?,?,?, ?,clock_timestamp(),0,clock_timestamp())",orderId,customer.getId(),"ETH","USDT");audit.record(customer.getId(),"ORDER_CANCEL_REQUESTED","order:"+orderId,"SUCCESS","INTENT_ONLY_ENGINE_RESULT_FOLLOWS");}));assertEquals(0,requests());}
    @Test void directSqlCannotOmitTheOriginalRequestAudit(){assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("INSERT INTO order_cancellations(order_id,user_id,base_mint,quote_mint,requested_at,attempts,next_attempt_at) VALUES(?,?,?, ?,clock_timestamp(),0,clock_timestamp())",orderId,customer.getId(),"BTC","USDT"));assertEquals(0,requests());}
    @Test void originalIdentityAndHistoryCannotBeOverwrittenOrDeleted(){request();for(String sql:List.of("UPDATE order_cancellations SET user_id="+maker.user().getId(),"UPDATE order_cancellations SET base_mint='ETH'","UPDATE order_cancellations SET requested_at=requested_at-interval '1 day'","DELETE FROM order_cancellations","TRUNCATE order_cancellations CASCADE"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(sql));assertEquals(1,requests());unchanged();}
    @Test void anAcknowledgedQueueCannotBeResetToUnconfirmed(){request();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("UPDATE order_cancellations SET acknowledged_at=NULL"));assertNotNull(cancellations.findById(orderId).orElseThrow().getAcknowledgedAt());unchanged();}
    @Test void attemptCountersCannotBeMovedBackwards(){request();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("UPDATE order_cancellations SET attempts=0"));assertEquals(1,cancellations.findById(orderId).orElseThrow().getAttempts());}
    @Test void customerHttpAcceptsPersistedUncertaintyWithoutLeakingTheEngineMessage()throws Exception{when(engine.cancelOrder(orderId,customer.getId(),"BTC/USDT")).thenThrow(new IllegalStateException("private-engine-password-do-not-return"));var response=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/cex/orders/"+orderId).header("Authorization","Bearer "+customerAccess)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isAccepted()).andReturn().getResponse().getContentAsString();assertFalse(response.contains("private-engine"));assertEquals(1,requests());unchanged();}
    @Test void customerHttpDoesNotLeakAFailedPersistenceMessage()throws Exception{doThrow(new IllegalStateException("private-storage-password-do-not-return")).when(audit).record(eq(customer.getId()),eq("ORDER_CANCEL_REQUESTED"),anyString(),anyString(),anyString());var response=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/cex/orders/"+orderId).header("Authorization","Bearer "+customerAccess)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest()).andReturn().getResponse().getContentAsString();assertFalse(response.contains("private-storage"));assertEquals(0,requests());verifyNoInteractions(engine);}
    @Test void anotherCustomersHttpRequestNeverStartsOrCreatesTheIntent()throws Exception{var other=users.saveAndFlush(dustin.cex.domains.auth.model.entity.User.builder().email(UUID.randomUUID()+"@test.invalid").passwordHash(hash).build());var login=tokens.saveAndFlush(dustin.cex.domains.auth.model.entity.RefreshToken.builder().userId(other.getId()).tokenHash(UUID.randomUUID().toString()).expiresAt(LocalDateTime.now().plusHours(1)).build());String token=jwt.generateAccessToken(other.getId(),login.getSessionId());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/cex/orders/"+orderId).header("Authorization","Bearer "+token)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());assertEquals(0,requests());verifyNoInteractions(engine);}
    @Test void externalIoReleasesTheOrderLockAndTransaction()throws Exception{
        try(var pool=java.util.concurrent.Executors.newSingleThreadExecutor()){
            when(engine.cancelOrder(orderId,customer.getId(),"BTC/USDT")).thenAnswer(call->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());var acquired=pool.submit(()->new TransactionTemplate(manager).execute(t->{jdbc.execute("SET LOCAL lock_timeout='200ms'");return orderRows.findByIdForUpdate(orderId).orElseThrow().getId();}));assertEquals(orderId,acquired.get(2,java.util.concurrent.TimeUnit.SECONDS));return true;});request();
        }unchanged();
    }
    @Test void anAlreadyFinishedOrderCannotCreateNewCancellationWork(){var row=orderRows.findById(orderId).orElseThrow();row.setStatus("filled");orderRows.saveAndFlush(row);assertThrows(IllegalArgumentException.class,()->request());assertEquals(0,requests());verifyNoInteractions(engine);}
    @Test void silentlyOmittedClaimAuditCannotCommitOrSendTheAttempt(){doNothing().when(audit).record(isNull(),eq("ORDER_CANCEL_ATTEMPT_STARTED"),anyString(),anyString(),anyString());request();assertEquals(1,requests());assertEquals(0,cancellations.findById(orderId).orElseThrow().getAttempts());verifyNoInteractions(engine);unchanged();}
    @Test void silentlyOmittedResponseAuditCannotCommitTheAcknowledgement(){doNothing().when(audit).record(isNull(),eq("ORDER_CANCEL_ATTEMPT_FINISHED"),anyString(),anyString(),anyString());request();assertEquals(1,cancellations.findById(orderId).orElseThrow().getAttempts());assertNull(cancellations.findById(orderId).orElseThrow().getAcknowledgedAt());unchanged();}
    @Test void aPreviousUncertainAuditCannotAuthorizeANewScheduleMutation(){when(engine.cancelOrder(orderId,customer.getId(),"BTC/USDT")).thenThrow(new IllegalStateException("격리 응답 유실"));request();var before=cancellations.findById(orderId).orElseThrow().getNextAttemptAt();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("UPDATE order_cancellations SET next_attempt_at=next_attempt_at+interval '1 day'"));assertEquals(before,cancellations.findById(orderId).orElseThrow().getNextAttemptAt());unchanged();}
    @Test void outputAuditFailureKeepsAcceptedIntentButNeverAFalsePositiveAcknowledgement()throws Exception{doNothing().when(audit).record(isNull(),eq("ORDER_CANCEL_ATTEMPT_FINISHED"),anyString(),anyString(),anyString());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/cex/orders/"+orderId).header("Authorization","Bearer "+customerAccess)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isAccepted());assertEquals(1,requests());assertNull(cancellations.findById(orderId).orElseThrow().getAcknowledgedAt());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE action='ORDER_CANCEL_REQUESTED' AND target=?",Long.class,"order:"+orderId));unchanged();}
}
